constexpr int fib(int n) {
    return (n <= 1) ? n : fib(n - 1) + fib(n - 2);
}

template <size_t... Is>
constexpr std::array<int, sizeof...(Is)> make_fib_array(std::index_sequence<Is...>) {
    // Array initialized entirely during compilation
    return {fib(Is)...};
}

constexpr auto FIB_SERIES = make_fib_array(std::make_index_sequence<6>{});

