template <typename T>
void debug_print(const T& value) {
    // Compile-time branch elimination (zero runtime overhead)
    if constexpr (std::is_integral_v<T>) {
        std::cout << "Int type: " << value;
    } else {
        // This branch is optimized away if T is integral
        std::cout << "Non-Int type.";
    }
}

