constexpr uint32_t hash_char(char c, uint32_t current) {
    return current * 31 + c;
}

constexpr uint32_t compile_hash(std::string_view s) {
    uint32_t hash = 0;
    for (size_t i = 0; i < s.length(); ++i) {
        hash = hash_char(s[i], hash);
    }
    return hash;
}

// Hash calculated once at compile time, stored directly
constexpr uint32_t KEY_HASH = compile_hash("critical_resource_name");
